const ownerAt = await Bun.file("/tmp/owner_at").text();

async function snapshot() {
  try {
    const r = await fetch("https://api.ivxholding.com/health");
    const h = await r.json();
    return { sha: h.commit, boot: h.bootTime, status: h.status, now: new Date().toISOString() };
  } catch (e) {
    return { err: String(e), now: new Date().toISOString() };
  }
}

async function task(tid) {
  try {
    const r = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/" + tid, {
      headers: { Authorization: "Bearer " + ownerAt },
    });
    const d = await r.json();
    return d.task ?? null;
  } catch (e) {
    return { err: String(e) };
  }
}

const oldSha = "1d31e9c4db42b71d5f75c392ef19468470697f29";
const start = Date.now();
const deadline = start + 9 * 60 * 1000; // 9 min polling budget
let iter = 0;
let last = null;
while (Date.now() < deadline) {
  iter++;
  const s = await snapshot();
  last = s;
  const changed = s.sha && s.sha !== oldSha;
  console.log(`[iter ${iter} ${s.now}] sha=${s.sha ?? "?"} boot=${s.boot ?? "?"} status=${s.status ?? "?"} ${changed ? "=== CHANGED ===" : ""}`);
  if (changed) {
    console.log("=== Deploy went live. Collecting evidence. ===");
    break;
  }
  await new Promise(r => setTimeout(r, 25000));
}
console.log("\n=== FINAL SNAPSHOT ===");
console.log(JSON.stringify(last, null, 2));
console.log("\n=== TASKS ===");
const t0d = await task("0d4f09e5-8afb-43a8-9a8d-db522887813b");
const t786 = await task("7862343b-3253-4824-8b86-4d0969c9372e");
console.log("0d4f09e5:", JSON.stringify({status: t0d?.status, terminal: t0d?.terminal, commitSha: t0d?.commitSha, resume: t0d?.resume_required, deployId: t0d?.deploy_id}));
console.log("7862343b:", JSON.stringify({status: t786?.status, terminal: t786?.terminal, commitSha: t786?.commitSha, resume: t786?.resume_required, deployId: t786?.deploy_id, error: t786?.error_message}));

