// Comprehensive evidence collector — run AFTER runtime SHA changes from 1d31e9c4
const ownerAt = await Bun.file("/tmp/owner_at").text();
const OLD_SHA = "1d31e9c4db42b71d5f75c392ef19468470697f29";

async function get(url, opts = {}) {
  const r = await fetch(url, { ...opts, headers: { Authorization: "Bearer " + ownerAt, ...(opts.headers || {}) } });
  const text = await r.text();
  let json;
  try { json = JSON.parse(text); } catch { json = null; }
  return { status: r.status, json, text };
}

// 1. Runtime SHA + 6. Live /health response
const h = await get("https://api.ivxholding.com/health");
console.log("\n=== 1+6. RUNTIME /health ===");
console.log(JSON.stringify({ status: h.status, body: h.json }, null, 2));

const runtimeSha = h.json?.commit;
if (!runtimeSha || runtimeSha === OLD_SHA) {
  console.log("\n!! Runtime SHA unchanged (" + runtimeSha + "). Deploy NOT yet live. Aborting evidence collection. !!");
  process.exit(0);
}
console.log("\nRuntime SHA: " + runtimeSha);
console.log("Boot: " + h.json?.bootTime);
console.log("Status: " + h.json?.status);

// 2. GitHub HEAD SHA (via public API, no auth needed for public repo)
const gh = await fetch("https://api.github.com/repos/ibb142/rork-global-real-estate-invest/commits/main");
const ghJson = await gh.json();
const githubSha = ghJson?.sha;
console.log("\n=== 2. GITHUB HEAD SHA ===");
console.log("GitHub main HEAD: " + githubSha);
console.log("GitHub commit message: " + ghJson?.commit?.message);

// 3. Render Deploy ID — via worker status if it exposes the latest deploy
const ws = await get("https://api.ivxholding.com/api/ivx/senior-developer/worker/status");
console.log("\n=== 3. WORKER STATUS (may include deployId) ===");
console.log(JSON.stringify({ status: ws.status, body: ws.json }, null, 2));

// 4+5. Proof Ledger ID + Task ID — list all senior-dev tasks
const tasks = await get("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs");
console.log("\n=== 4+5. ALL SENIOR-DEV TASKS ===");
const taskList = tasks.json?.tasks || tasks.json?.data || [];
console.log("Task count: " + taskList.length);
for (const t of taskList) {
  console.log("\nTask " + (t.id ?? t.task_id ?? "?").slice(0, 8) + ":");
  console.log("  status=" + t.status + " terminal=" + t.terminal);
  console.log("  commitSha=" + (t.commitSha ?? t.commit_sha ?? "null"));
  console.log("  deployId=" + (t.deployId ?? t.deploy_id ?? "null"));
  console.log("  proofLedgerId=" + (t.proofLedgerId ?? t.proof_ledger_id ?? "null"));
  console.log("  resume_required=" + t.resume_required);
  console.log("  error=" + (t.errorMessage ?? t.error_message ?? "null"));
  console.log("  files=" + JSON.stringify(t.filesChanged ?? t.files_changed ?? t.files ?? "null"));
}

// 7. SHA parity
console.log("\n=== 7. SHA PARITY ===");
console.log("GitHub:  " + githubSha);
console.log("Runtime: " + runtimeSha);
console.log("Match:   " + (githubSha === runtimeSha));

// 8. Final task status summary
console.log("\n=== 8. TASK STATUS SUMMARY ===");
let verifiedCount = 0, failedCount = 0, blockedCount = 0, otherCount = 0;
for (const t of taskList) {
  const s = t.status;
  if (s === "VERIFIED") verifiedCount++;
  else if (s === "FAILED") failedCount++;
  else if (s === "BLOCKED") blockedCount++;
  else otherCount++;
}
console.log("VERIFIED: " + verifiedCount + "  FAILED: " + failedCount + "  BLOCKED: " + blockedCount + "  OTHER: " + otherCount);

// 9. APK version — check live APK endpoint
const apk = await fetch("https://ivxholding.com/apk/ivx-holdings-v1.4.8.apk", { method: "HEAD" });
console.log("\n=== 9. APK ===");
console.log("v1.4.8 HEAD status: " + apk.status + " content-length: " + apk.headers.get("content-length") + " ETag: " + apk.headers.get("etag"));
const apk49 = await fetch("https://ivxholding.com/apk/ivx-holdings-v1.4.9.apk", { method: "HEAD" });
console.log("v1.4.9 HEAD status: " + apk49.status);

// 10. End-to-end autonomous task demonstration — check each task's checkpoint history
console.log("\n=== 10. END-TO-END AUTONOMOUS TASK DEMONSTRATION ===");
for (const t of taskList) {
  const tid = t.id ?? t.task_id;
  if (!tid) continue;
  const detail = await get("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/" + tid);
  const dt = detail.json?.task ?? detail.json;
  console.log("\nTask " + tid.slice(0, 8) + " checkpoint_history:");
  const hist = dt?.checkpoint_history || dt?.checkpointHistory || [];
  for (const c of hist) {
    console.log("  - " + (c.checkpoint ?? c.stage ?? "?") + " @ " + (c.at ?? c.timestamp ?? "?") + " : " + (c.note ?? c.message ?? ""));
  }
}

